module.exports = async (args) => {
  const french = ['fre', 'fra', 'fr', 'french'];
  const english = ['eng', 'en', 'english'];
  const maxWidth = 1920;
  const maxHeight = 1080;
  const command = args.variables.ffmpegCommand;
  const language = (stream) => String((stream.tags && stream.tags.language) || 'und').toLowerCase().split('-')[0];
  const isFrench = (stream) => french.includes(language(stream));
  const remove = (stream, reason) => {
    stream.removed = true;
    args.jobLog(`Removing stream ${stream.index}: ${reason}`);
  };

  const fs = require('fs');
  const path = require('path');
  const libraryFile = args.originalLibraryFile._id;
  const folder = path.dirname(libraryFile);
  const base = path.basename(libraryFile, path.extname(libraryFile));
  const subtitleCodecs = { srt: 'subrip', ass: 'ass', ssa: 'ass', vtt: 'webvtt' };
  const subtitleFlags = ['forced', 'hi', 'sdh', 'cc'];
  const threeLetters = { fr: 'fre', en: 'eng', ja: 'jpn' };
  const sidecars = fs.readdirSync(folder)
    .filter((name) => name.startsWith(`${base}.`))
    .map((name) => {
      const parts = name.slice(base.length + 1).split('.');
      const extension = parts.pop().toLowerCase();
      const [code = '', ...flags] = parts.map((part) => part.toLowerCase());
      return { file: path.join(folder, name), extension, code, flags };
    })
    .filter((sidecar) => subtitleCodecs[sidecar.extension]
      && /^[a-z]{2,3}(-[a-z]{2,4})?$/.test(sidecar.code)
      && sidecar.flags.every((flag) => subtitleFlags.includes(flag)));
  if (sidecars.length > 0) {
    const mainInput = sidecars.length;
    command.streams.forEach((stream) => {
      stream.mapArgs = ['-map', `${mainInput}:${stream.index}`];
    });
    sidecars.forEach((sidecar, input) => {
      const lang = threeLetters[sidecar.code] || sidecar.code;
      const forced = sidecar.flags.includes('forced');
      const hearingImpaired = sidecar.flags.some((flag) => flag !== 'forced');
      const outputArgs = ['-metadata:s:{outputIndex}', `language=${lang}`];
      if (forced || hearingImpaired) {
        outputArgs.push('-disposition:{outputIndex}', forced ? 'forced' : 'hearing_impaired');
      }
      command.overallInputArguments.push('-i', sidecar.file);
      command.streams.push({
        index: `sidecar ${path.basename(sidecar.file)}`,
        codec_type: 'subtitle',
        codec_name: subtitleCodecs[sidecar.extension],
        tags: { language: lang },
        disposition: { forced: forced ? 1 : 0 },
        removed: false,
        sidecar: true,
        mapArgs: ['-map', `${input}:0`],
        inputArgs: [],
        outputArgs,
      });
      args.jobLog(`Embedding subtitle file ${sidecar.file}`);
    });
    command.overallOuputArguments.push('-map_metadata', `${mainInput}`, '-map_chapters', `${mainInput}`);
    args.variables.user = args.variables.user || {};
    args.variables.user.sidecars = JSON.stringify(sidecars.map((sidecar) => sidecar.file));
  }

  const videos = command.streams.filter((stream) => stream.codec_type === 'video');
  if (videos.length === 0) {
    throw new Error('No video stream');
  }
  const video = videos[0];
  videos.slice(1).forEach((stream) => remove(stream, 'extra video stream'));

  const audios = command.streams.filter((stream) => stream.codec_type === 'audio');
  const foreign = audios.find((stream) => !isFrench(stream));
  const original = foreign ? language(foreign) : 'fre';
  args.jobLog(`Original audio language: ${original}`);
  audios
    .filter((stream) => !isFrench(stream) && language(stream) !== original)
    .forEach((stream) => remove(stream, `audio in ${language(stream)}`));

  const subtitleLanguages = [...french, ...english];
  command.streams
    .filter((stream) => stream.codec_type === 'subtitle' && !stream.sidecar)
    .forEach((stream) => {
      if (!subtitleLanguages.includes(language(stream))) {
        remove(stream, `subtitle in ${language(stream)}`);
      } else if (['eia_608', 'timed_id3'].includes(stream.codec_name)) {
        remove(stream, `${stream.codec_name} subtitle not supported by MKV`);
      } else if (stream.codec_name === 'mov_text') {
        stream.outputArgs.push('-c:{outputIndex}', 'srt');
      }
    });

  command.streams
    .filter((stream) => stream.codec_type === 'data')
    .forEach((stream) => remove(stream, 'data stream'));
  command.streams
    .filter((stream) => stream.codec_type === 'attachment' && stream.disposition && stream.disposition.attached_pic)
    .forEach((stream) => remove(stream, 'cover picture'));

  const tooLarge = video.width > maxWidth || video.height > maxHeight;
  if (video.codec_name === 'hevc' && !tooLarge) {
    args.jobLog(`Video already H265 ${video.width}x${video.height}, copied as is`);
  } else {
    args.jobLog(`Encoding ${video.codec_name} ${video.width}x${video.height} to H265`);
    video.outputArgs.push('-c:{outputIndex}', 'libx265', '-crf', '22', '-preset', 'medium');
    if (tooLarge) {
      video.outputArgs.push(
        '-filter:{outputIndex}',
        `scale=${maxWidth}:${maxHeight}:force_original_aspect_ratio=decrease:force_divisible_by=2`,
      );
    }
    command.shouldProcess = true;
  }

  return {
    outputFileObj: args.inputFileObj,
    outputNumber: 1,
    variables: args.variables,
  };
};

module.exports = async (args) => {
  const fs = require('fs');
  const sidecars = JSON.parse((args.variables.user && args.variables.user.sidecars) || '[]');
  sidecars.forEach((file) => {
    fs.rmSync(file, { force: true });
    args.jobLog(`Deleted embedded subtitle file ${file}`);
  });

  const libraryFile = args.originalLibraryFile._id;
  const arr = libraryFile.startsWith('/data/media/movies/')
    ? { name: 'Radarr', url: 'http://radarr:7878', key: process.env.RADARR_API_KEY, list: 'movie', command: (id) => ({ name: 'RescanMovie', movieId: id }) }
    : { name: 'Sonarr', url: 'http://sonarr:8989', key: process.env.SONARR_API_KEY, list: 'series', command: (id) => ({ name: 'RescanSeries', seriesId: id }) };
  if (!arr.key) {
    args.jobLog(`No ${arr.name} API key, ${arr.name} sees the new file at its next refresh`);
  } else {
    try {
      const headers = { 'X-Api-Key': arr.key, 'Content-Type': 'application/json' };
      const response = await fetch(`${arr.url}/api/v3/${arr.list}`, { headers });
      if (!response.ok) {
        throw new Error(`HTTP ${response.status}`);
      }
      const items = await response.json();
      const item = items.find((entry) => libraryFile.startsWith(`${entry.path}/`));
      if (!item) {
        args.jobLog(`${arr.name} does not know ${libraryFile}`);
      } else {
        const rescan = await fetch(`${arr.url}/api/v3/command`, {
          method: 'POST',
          headers,
          body: JSON.stringify(arr.command(item.id)),
        });
        if (!rescan.ok) {
          throw new Error(`HTTP ${rescan.status}`);
        }
        args.jobLog(`${arr.name} rescans ${item.path}`);
      }
    } catch (err) {
      args.jobLog(`Could not tell ${arr.name} about the new file: ${err.message}`);
    }
  }

  return {
    outputFileObj: args.inputFileObj,
    outputNumber: 1,
    variables: args.variables,
  };
};
